// TH18 v1.00a Stage 4 mid-stage wave w02.
// Source: st04.ecl.txt MainSub01 S:867-879 (first 8 enemies, 4 pairs at 0/40/80/120).
// Enemy body: st04.ecl.txt Cir01 S:68-139 (Cir01_at S:91-139).
const TIME_LIMIT: int = 720;          // 120 shell buffer + 360 source schedule + 240 tail estimate
const OPENING_BUFFER: int = 120;
const SOURCE_SCHEDULE: int = 360;     // MainSub01 w02 local 0..360, including the S:879 wait(200)
const TH18_RING_BALL2: int = 464;     // TH18 type 7 RingBall2, radius 4

// Source Cir01_at S:91-139. etAim(0,3)=fixed-direction ring; one RANDRAD base per volley.
async sub cir01_fire() {
    wait(80);                         // Cir01 S:81 wait(80) before @Cir01_at()
    var rank: int = global(GVAR_RANK);
    var n: int = 15;                  // !E etCount(0,15,1)
    var speed: fx = 1.2fx;            // !E etSpeed
    var gap: int = 100;               // !E wait 100 (unused with one volley)
    var rounds: int = 1;              // diffI($A,1,3,3,3)
    if rank == RANK_NORMAL {
        n = 25; speed = 1.8fx; gap = 80; rounds = 3;
    } else if rank == RANK_HARD {
        n = 30; speed = 1.8fx; gap = 70; rounds = 3;
    } else if rank >= RANK_LUNATIC {
        n = 42; speed = 2.3fx; gap = 70; rounds = 3;
    }
    for r in 0..rounds {
        sh_reset(0);
        sh_sprite(0, TH18_RING_BALL2, 2); // etSprite(0,7,2)
        sh_ring(0, 1);                    // etAim(0,3), fixed-direction full ring
        sh_aim(0, 0);
        sh_count(0, n, 1);                // etCount(0,[-1],1)
        sh_angle(0, (rand(65536)) as angle, 0deg); // Cir01_at S:123 etAngle(0,%RANDRAD,0)
        sh_speed(0, speed, 0fx);          // etSpeed(0,[-1.0f],1.0f), one layer
        // etEx(0,0,2,1,...) ANIM a=1 keeps position -= 4*initial velocity (source S:119).
        sh_dist(0, -4fx * speed);
        sh_fire(0);
        if r + 1 < rounds { wait(gap); }
    }
}

// Cir01 S:68-89: ABS moveVel 4.4 then 80-frame linear ramp to 0.4 (S:78-79),
// plus REL ellipse theta=0, omega=2deg/frame, r=10, beta=ABS_ANGLE=90deg, s=0 (S:80).
// Circular-motion.md: with s=0 the REL offset is 10*cos(theta) on the fixed beta axis,
// so the source position is ABS(t) + (10*cos(theta), 0). Target has no two-layer mover:
// write the composed position once per frame; theta/r/beta are kept in script state.
async sub cir01(x0: fx) {
    set_invuln(65535);
    set_hitbox(8fx);                  // setHitbox(16,16), ordinary circle radius = width*0.5
    set_hurtbox(14fx);                // setHurtbox(28,28), damage disabled by invuln
    var py: fx = -32fx;
    var phase: angle = 0deg;
    var speed: fx = 4.4fx;
    // Non-Time ellipse setter applies theta=0 at once, before the first movement tick.
    move_to(0, x0 + 10fx, py, EASE_LINEAR);
    spawn cir01_fire();
    // Tick positions after source movement tick n: y(n)=-32+sum(4.4-0.05*(k-1)), 1<=k<=80.
    for i in 0..80 {
        wait(1);
        py = py + speed;
        phase = phase + 2deg;         // 0.034906585 rad/frame
        speed = speed - 0.05fx;       // linear 4.4 -> 0.4 over 80 frames
        move_to(0, x0 + 10fx * cos(phase), py, EASE_LINEAR);
    }
    wait(1);
    py = py + 0.4fx;
    phase = phase + 2deg;
    move_to(0, x0 + 10fx * cos(phase), py, EASE_LINEAR);
    loop {
        wait(1);
        py = py + 0.4fx;
        phase = phase + 2deg;
        move_to(0, x0 + 10fx * cos(phase), py, EASE_LINEAR);
    }
}

// MainSub01 S:867-879: four relative enmCreate pairs. The stage parent FINAL is the origin.
async sub wave() {
    wait(OPENING_BUFFER - 2);         // director (frame 1) + pattern (frame 2) start two frames after main
    _ = spawn_enemy(128fx, -32fx, 380, 0, 0, 0, cir01(128fx));
    _ = spawn_enemy(-128fx, -32fx, 380, 0, 0, 0, cir01(-128fx));
    wait(40);
    _ = spawn_enemy(64fx, -32fx, 380, 0, 0, 0, cir01(64fx));
    _ = spawn_enemy(-64fx, -32fx, 380, 0, 0, 0, cir01(-64fx));
    wait(40);
    _ = spawn_enemy(128fx, -32fx, 380, 0, 0, 0, cir01(128fx));
    _ = spawn_enemy(-128fx, -32fx, 380, 0, 0, 0, cir01(-128fx));
    wait(40);
    _ = spawn_enemy(64fx, -32fx, 380, 0, 0, 0, cir01(64fx));
    _ = spawn_enemy(-64fx, -32fx, 380, 0, 0, 0, cir01(-64fx));
    wait(40);
    wait(200);                        // S:879, leading to the next group (w03 not included)
}

async sub director() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(0fx);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, director);
    loop { wait(600); }
}
